mapper.select:
SELECT o.ORDER_NO AS orderNo, o.ORDER_ID AS orderId, o.ORDERED_AT AS orderedAt, o.ORDER_STATUS AS orderStatus, o.CANCEL_STATUS AS cancelStatus, o.PURCHASE_CONFIRM_STATUS AS purchaseConfirmStatus, o.PURCHASE_CONFIRMED_AT AS purchaseConfirmedAt, NVL(d.DELIVERY_STATUS, 'READY') AS deliveryStatus, d.CARRIER_CODE AS carrierCode, d.COURIER_NAME AS courierName, d.TRACKING_NO AS trackingNo, d.WAYBILL_STATUS AS waybillStatus, d.WAYBILL_ASSIGNED_AT AS waybillAssignedAt, d.PICKED_UP_AT AS pickedUpAt, d.IN_TRANSIT_AT AS inTransitAt, d.DELIVERED_AT AS deliveredAt, CASE WHEN oi.ITEM_COUNT <= 1 THEN oi.FIRST_PRODUCT_NAME ELSE oi.FIRST_PRODUCT_NAME || ' +' || TO_CHAR(oi.ITEM_COUNT - 1) END AS displayProductName, oi.ITEM_COUNT AS itemCount, o.FINAL_AMOUNT AS finalAmount, oi.TOTAL_SAVED_AMOUNT AS totalSavedAmount FROM OFT_ORDERS o LEFT JOIN OFT_DELIVERY d ON d.ORDER_NO = o.ORDER_NO JOIN ( SELECT agg.ORDER_NO, firstItem.PRODUCT_NAME AS FIRST_PRODUCT_NAME, agg.ITEM_COUNT, agg.TOTAL_SAVED_AMOUNT FROM ( SELECT ORDER_NO, COUNT(*) AS ITEM_COUNT, SUM(NVL(SAVED_AMOUNT, 0)) AS TOTAL_SAVED_AMOUNT, MIN(ORDER_ITEM_NO) AS FIRST_ORDER_ITEM_NO FROM OFT_ORDER_ITEM GROUP BY ORDER_NO ) agg JOIN OFT_ORDER_ITEM firstItem ON firstItem.ORDER_ITEM_NO = agg.FIRST_ORDER_ITEM_NO ) oi ON oi.ORDER_NO = o.ORDER_NO WHERE o.USER_NO = #{userNo}
AND NVL(d.DELIVERY_STATUS, 'READY') = #{deliveryStatus}
AND o.ORDERED_AT >= #{dateFrom}
AND o.ORDERED_AT < #{dateTo}
ORDER BY o.ORDERED_AT DESC

SELECT ORDER_NO
FROM OFT_ORDERS
WHERE ORDER_ID = #{_parameter}
